-- Delete in reverse dependency order for both orgs
DELETE FROM events 
WHERE organization_id IN ('10000000-0000-0000-0000-000000000000', '10000000-0000-0000-0000-000000000001')
  OR from_user_id IN (
    '00000000-0000-0000-0000-000000000001',
    '00000000-0000-0000-0000-000000000002',
    '00000000-0000-0000-0000-000000000003'
  )
  OR to_user_id IN (
    '00000000-0000-0000-0000-000000000001',
    '00000000-0000-0000-0000-000000000002',
    '00000000-0000-0000-0000-000000000003'
  );

DELETE FROM presence WHERE organization_id IN ('10000000-0000-0000-0000-000000000000', '10000000-0000-0000-0000-000000000001');
DELETE FROM organization_invitations WHERE organization_id IN ('10000000-0000-0000-0000-000000000000', '10000000-0000-0000-0000-000000000001');
DELETE FROM organization_members WHERE organization_id IN ('10000000-0000-0000-0000-000000000000', '10000000-0000-0000-0000-000000000001');
DELETE FROM cabins WHERE organization_id IN ('10000000-0000-0000-0000-000000000000', '10000000-0000-0000-0000-000000000001');
DELETE FROM maps WHERE organization_id IN ('10000000-0000-0000-0000-000000000000', '10000000-0000-0000-0000-000000000001');
DELETE FROM organizations WHERE id IN ('10000000-0000-0000-0000-000000000000', '10000000-0000-0000-0000-000000000001');
DELETE FROM users WHERE id IN (
  '00000000-0000-0000-0000-000000000001',
  '00000000-0000-0000-0000-000000000002',
  '00000000-0000-0000-0000-000000000003',
  '00000000-0000-0000-0000-000000000004',
  '00000000-0000-0000-0000-000000000005',
  '00000000-0000-0000-0000-000000000006'
);
DELETE FROM auth.users WHERE id IN (
  '00000000-0000-0000-0000-000000000001',
  '00000000-0000-0000-0000-000000000002',
  '00000000-0000-0000-0000-000000000003',
  '00000000-0000-0000-0000-000000000004',
  '00000000-0000-0000-0000-000000000005',
  '00000000-0000-0000-0000-000000000006'
);

DELETE FROM audit_logs WHERE organization_id IN ('10000000-0000-0000-0000-000000000000', '10000000-0000-0000-0000-000000000001');

